// MARK: - Models/Overlays/OverlayBackdrop.swift

/// What fills the frame behind an overlay card while it is on screen.
///
/// A card laid straight over the speaker reads as pasted on. Most cutaways in
/// a talking-head edit want the room to step back: either the speaker's own
/// picture blurred and dimmed (frosted), or a calm generated surface. Both are
/// drawn by the compositor between the speaker and the card, so captions and
/// anything in front of the card are untouched.
///
/// `nil` on an overlay means nothing is drawn behind it, which is every
/// overlay saved before this existed.
struct OverlayBackdrop: Codable, Equatable, Hashable, Sendable {
    enum Kind: String, Codable, Sendable {
        /// The speaker's own footage, blurred and slightly darkened.
        case frosted
        /// A generated surface. See `BackdropPreset`.
        case preset
        /// A picture in the project's media, filling the frame: one the
        /// creator imported, or one generated from a sentence.
        case image
    }

    var kind: Kind
    /// Which surface, when `kind` is `.preset`.
    var preset: BackdropPreset?
    /// The preset's colours as `#RRGGBB`, background first, in the order of
    /// `BackdropPreset.colorNames`. `nil` uses the preset's own.
    var colors: [String]?
    /// The picture, when `kind` is `.image`.
    var mediaID: UUID?

    /// The colours a preset is drawn with: the creator's where they set them,
    /// the preset's own everywhere else.
    var resolvedColors: [String] {
        guard let preset else { return [] }
        return preset.resolvedColors(colors)
    }

    /// The same look, whatever its colours. What a swatch compares against.
    func isSameLook(as other: OverlayBackdrop?) -> Bool {
        guard let other else { return false }
        return kind == other.kind && preset == other.preset && mediaID == other.mediaID
    }

    static let frosted = OverlayBackdrop(kind: .frosted)
    static func preset(_ preset: BackdropPreset) -> OverlayBackdrop {
        OverlayBackdrop(kind: .preset, preset: preset)
    }

    /// How long the backdrop takes to arrive once the card is up. Short enough
    /// to feel like the card bringing it, long enough not to read as a cut.
    static let fadeIn: Double = 0.35

    static func image(_ mediaID: UUID) -> OverlayBackdrop {
        OverlayBackdrop(kind: .image, mediaID: mediaID)
    }

    /// A backdrop that can be drawn. A preset or image with nothing named is
    /// not one.
    var isDrawable: Bool {
        switch kind {
        case .frosted: true
        case .preset: preset != nil
        case .image: mediaID != nil
        }
    }

    /// The token Chirpy and the action contract use: `frosted`, a preset's
    /// raw value, or `none`.
    var token: String {
        switch kind {
        case .frosted: "frosted"
        case .preset: preset?.rawValue ?? "none"
        case .image: "image"
        }
    }

    /// Reads a token back. `none` and anything unknown come back `nil`.
    init?(token: String) {
        if token == "frosted" {
            self = .frosted
        } else if let preset = BackdropPreset(rawValue: token) {
            self = .preset(preset)
        } else {
            return nil
        }
    }

    init(kind: Kind, preset: BackdropPreset? = nil, colors: [String]? = nil, mediaID: UUID? = nil) {
        self.kind = kind
        self.preset = preset
        self.colors = colors
        self.mediaID = mediaID
    }
}

/// The generated surfaces. Drawn in code from a few numbers each (see
/// `BackdropPresetRenderer`), so they cost no disk space and look the same at
/// any export size.
///
/// All of them are dark and still on purpose. White captions with a black
/// outline sit 75 to 85% down the frame and have to stay readable there, and a
/// backdrop that moves or glows pulls the eye off the product shown on the
/// card.
enum BackdropPreset: String, Codable, CaseIterable, Identifiable, Sendable {
    /// Deep navy, a tall soft glow and a brand-blue halo behind the card.
    case navyGlow
    /// Faint teal and violet bands across the top of a near-black sky.
    case aurora
    /// Soft rays falling from above the frame.
    case lightRays
    /// A dark mesh of plum, ember and navy, with heavier grain.
    case grainient
    /// A faint grid that fades out toward the edges.
    case shapeGrid

    var id: String { rawValue }

    var title: String {
        switch self {
        case .navyGlow: "Navy glow"
        case .aurora: "Aurora"
        case .lightRays: "Light rays"
        case .grainient: "Grainient"
        case .shapeGrid: "Grid"
        }
    }

    /// What each colour does, background first. The colour controls are
    /// labelled with these.
    var colorNames: [String] {
        switch self {
        case .navyGlow: ["Background", "Glow", "Halo"]
        case .aurora: ["Sky", "Upper band", "Lower band"]
        case .lightRays: ["Background", "Rays", "Light"]
        case .grainient: ["Background", "Top left", "Right", "Bottom"]
        case .shapeGrid: ["Background", "Lines", "Glow"]
        }
    }

    /// The colours the preset was tuned with.
    var defaultColors: [String] {
        switch self {
        case .navyGlow: ["#0D1B3A", "#284E92", "#5488F5"]
        case .aurora: ["#0A0F1E", "#349692", "#604EB2"]
        case .lightRays: ["#080A12", "#96B2E4", "#7896D2"]
        case .grainient: ["#0B0910", "#461A42", "#964028", "#183484"]
        case .shapeGrid: ["#0A0C12", "#96A5C8", "#283C6E"]
        }
    }

    /// `custom` laid over the defaults slot by slot, so a short or partly
    /// invalid list still gives every slot a colour.
    func resolvedColors(_ custom: [String]?) -> [String] {
        defaultColors.enumerated().map { index, fallback in
            guard let custom, custom.indices.contains(index), BackdropPreset.isHex(custom[index]) else { return fallback }
            return custom[index].uppercased()
        }
    }

    static func isHex(_ value: String) -> Bool {
        let digits = value.hasPrefix("#") ? value.dropFirst() : Substring(value)
        return digits.count == 6 && digits.allSatisfy(\.isHexDigit)
    }
}

// MARK: - Services/Backdrop/BackdropShading.swift

/// The arithmetic the backdrop presets are drawn with: a colour, a blend, and
/// the gradient shapes CSS has names for. Written out so a preset reads like
/// the CSS it was tuned from, and so the same numbers can be ported to the
/// agent skill's renderer line for line.
struct ShadeColor: Equatable, Sendable {
    var r: Double
    var g: Double
    var b: Double

    /// From 0 to 255 per channel, the way the references were written.
    init(_ r: Double, _ g: Double, _ b: Double) {
        self.r = r / 255
        self.g = g / 255
        self.b = b / 255
    }

    init(unit r: Double, _ g: Double, _ b: Double) {
        self.r = r
        self.g = g
        self.b = b
    }

    /// From `#RRGGBB`. Anything else reads as black.
    init(hexString: String) {
        let digits = hexString.hasPrefix("#") ? String(hexString.dropFirst()) : hexString
        self.init(hex: UInt32(digits, radix: 16) ?? 0)
    }

    init(hex: UInt32) {
        self.init(Double((hex >> 16) & 0xFF), Double((hex >> 8) & 0xFF), Double(hex & 0xFF))
    }

    /// `top` laid over this colour at `alpha`.
    func under(_ top: ShadeColor, alpha: Double) -> ShadeColor {
        let a = Shade.clamp(alpha)
        return ShadeColor(unit: r + (top.r - r) * a, g + (top.g - g) * a, b + (top.b - b) * a)
    }

    /// This colour mixed toward `other`, by `t`.
    func mixed(with other: ShadeColor, _ t: Double) -> ShadeColor {
        under(other, alpha: t)
    }

    func scaled(_ factor: Double) -> ShadeColor {
        ShadeColor(unit: r * factor, g * factor, b * factor)
    }

    func adding(_ amount: Double) -> ShadeColor {
        ShadeColor(unit: r + amount, g + amount, b + amount)
    }
}

/// A colour and an opacity at a point along a gradient, from 0 to 1.
struct ShadeStop: Sendable {
    let at: Double
    let color: ShadeColor
    let alpha: Double

    init(_ at: Double, _ color: ShadeColor, _ alpha: Double) {
        self.at = at
        self.color = color
        self.alpha = alpha
    }
}

enum Shade {
    static func clamp(_ x: Double, _ lo: Double = 0, _ hi: Double = 1) -> Double {
        min(hi, max(lo, x))
    }

    static func smoothstep(_ edge0: Double, _ edge1: Double, _ x: Double) -> Double {
        let t = clamp((x - edge0) / (edge1 - edge0))
        return t * t * (3 - 2 * t)
    }

    /// Where a gradient is at `t`, as colour and opacity, interpolated
    /// straight between the stops either side the way CSS does.
    static func sample(_ stops: [ShadeStop], at t: Double) -> (color: ShadeColor, alpha: Double) {
        guard let first = stops.first, let last = stops.last else {
            return (ShadeColor(0, 0, 0), 0)
        }
        if t <= first.at { return (first.color, first.alpha) }
        if t >= last.at { return (last.color, last.alpha) }
        for index in 1 ..< stops.count where t <= stops[index].at {
            let a = stops[index - 1]
            let b = stops[index]
            let k = (t - a.at) / max(0.000_001, b.at - a.at)
            return (a.color.mixed(with: b.color, k), a.alpha + (b.alpha - a.alpha) * k)
        }
        return (last.color, last.alpha)
    }

    /// How far a point is from the middle of a CSS `radial-gradient(rx ry at
    /// cx cy)`, where 1 is the edge of the ellipse. All in fractions of the
    /// frame, as CSS percentages are.
    static func ellipse(_ u: Double, _ v: Double, cx: Double, cy: Double, rx: Double, ry: Double) -> Double {
        let dx = (u - cx) / rx
        let dy = (v - cy) / ry
        return (dx * dx + dy * dy).squareRoot()
    }

    /// The colour a radial gradient lays over `base` at this point.
    static func radial(
        _ base: ShadeColor,
        _ u: Double, _ v: Double,
        cx: Double, cy: Double, rx: Double, ry: Double,
        stops: [ShadeStop]
    ) -> ShadeColor {
        let sample = sample(stops, at: ellipse(u, v, cx: cx, cy: cy, rx: rx, ry: ry))
        return base.under(sample.color, alpha: sample.alpha)
    }

    /// A smooth bump: 1 at `centre`, falling off over `width` either side.
    static func gaussian(_ x: Double, centre: Double, width: Double) -> Double {
        let d = (x - centre) / width
        return exp(-d * d)
    }

    /// The same noise for the same pixel on every frame and every machine, so
    /// grain holds still and an export matches its preview.
    static func hash(_ x: Int, _ y: Int, seed: UInt32 = 7) -> Double {
        var h = UInt32(truncatingIfNeeded: x) &* 374_761_393
            &+ UInt32(truncatingIfNeeded: y) &* 668_265_263
            &+ seed &* 2_246_822_519
        h = (h ^ (h >> 13)) &* 1_274_126_177
        h ^= h >> 16
        return Double(h) / Double(UInt32.max)
    }
}

// MARK: - Services/Backdrop/BackdropPresetShaders.swift

/// One preset drawn at a point. `u` runs 0 to 1 left to right and `v` 0 to 1
/// top to bottom; `focus` is the middle of the card the backdrop sits behind,
/// in the same units, so a halo can light the card rather than the frame.
///
/// The looks are the reactbits.dev and grainient.supply ones (aurora, light
/// rays, shape grid, grainient) with the volume turned down: lower contrast,
/// darker, and nothing moving. Every one keeps the band 75 to 85% down the
/// frame dark, where white outlined captions sit.
struct BackdropPresetShader: Sendable {
    let preset: BackdropPreset
    /// Width over height of the frame, so round things stay round.
    let aspect: Double
    let focus: (x: Double, y: Double)
    /// The preset's colours, background first, resolved against its defaults.
    let palette: [ShadeColor]

    init(preset: BackdropPreset, aspect: Double, focus: (x: Double, y: Double), colors: [String]? = nil) {
        self.preset = preset
        self.aspect = aspect
        self.focus = focus
        palette = preset.resolvedColors(colors).map(ShadeColor.init(hexString:))
    }

    private func slot(_ index: Int) -> ShadeColor {
        palette.indices.contains(index) ? palette[index] : ShadeColor(0, 0, 0)
    }

    /// How much fine grain is added, in 0 to 1 of full scale. Enough to stop
    /// the gradients banding in an 8-bit phone export and no more.
    var grain: Double {
        switch preset {
        case .grainient: 0.055
        case .navyGlow: 0.03
        default: 0.025
        }
    }

    func color(_ u: Double, _ v: Double) -> ShadeColor {
        let shaded: ShadeColor
        switch preset {
        case .navyGlow: shaded = navyGlow(u, v)
        case .aurora: shaded = aurora(u, v)
        case .lightRays: shaded = lightRays(u, v)
        case .grainient: shaded = grainient(u, v)
        case .shapeGrid: shaded = shapeGrid(u, v)
        }
        return captionBand(shaded, v)
    }

    // MARK: - Presets

    /// The TEF promo frame: deep navy, a tall soft glow, a brand-blue halo
    /// spilling just past the card's edges, and a dark edge. Ported stop for
    /// stop from `glow-backdrop.tsx`.
    private func navyGlow(_ u: Double, _ v: Double) -> ShadeColor {
        let base = slot(0)
        let glow = slot(1)
        let halo = slot(2)
        let top = base
        let middle = base.scaled(0.86)
        let bottom = base.scaled(0.56)
        var c = v < 0.52 ? top.mixed(with: middle, v / 0.52) : middle.mixed(with: bottom, (v - 0.52) / 0.48)
        let fy = focus.y
        c = Shade.radial(c, u, v, cx: focus.x, cy: fy + 0.01, rx: 0.64, ry: 0.46, stops: [
            ShadeStop(0, glow, 0.95),
            ShadeStop(0.42, glow.scaled(0.68), 0.6),
            ShadeStop(1, glow.scaled(0.36), 0),
        ])
        c = Shade.radial(c, u, v, cx: focus.x, cy: fy, rx: 0.66, ry: 0.44, stops: [
            ShadeStop(0, halo, 0.5),
            ShadeStop(0.64, halo.scaled(0.9), 0.36),
            ShadeStop(1, halo.scaled(0.85), 0),
        ])
        c = Shade.radial(c, u, v, cx: 0.5, cy: 0.44, rx: 1.2, ry: 0.78, stops: [
            ShadeStop(0.52, base.scaled(0.32), 0),
            ShadeStop(1, base.scaled(0.32), 0.72),
        ])
        return c
    }

    /// Two slow curtains of light across the top: muted teal over a violet
    /// one, on a sky that falls to near black.
    private func aurora(_ u: Double, _ v: Double) -> ShadeColor {
        var c = slot(0).mixed(with: slot(0).scaled(0.48), Shade.smoothstep(0, 0.9, v))
        let wave1 = 0.20 + 0.045 * sin(u * 5.2 + 0.6) + 0.02 * sin(u * 11.0 + 2.1)
        let wave2 = 0.30 + 0.05 * sin(u * 4.1 + 2.4) + 0.015 * sin(u * 9.0 + 0.4)
        let teal = Shade.gaussian(v, centre: wave1, width: 0.075) * (0.7 + 0.3 * sin(u * 3.1 + 1.0))
        let violet = Shade.gaussian(v, centre: wave2, width: 0.10) * (0.6 + 0.4 * sin(u * 2.3 + 3.0))
        c = c.under(slot(1), alpha: 0.32 * teal)
        c = c.under(slot(2), alpha: 0.28 * violet)
        // A faint wash where the curtains glow onto the sky below them.
        c = c.under(slot(1).mixed(with: slot(2), 0.5).scaled(0.62), alpha: 0.12 * Shade.gaussian(v, centre: 0.38, width: 0.22))
        return c
    }

    /// Soft rays from a light just above the frame, fading by a third of the
    /// way down.
    private func lightRays(_ u: Double, _ v: Double) -> ShadeColor {
        var c = slot(0).mixed(with: slot(0).scaled(0.6), v)
        let ox = 0.5
        let oy = -0.12
        let dx = (u - ox) * aspect
        let dy = v - oy
        let angle = atan2(dx, dy)
        let distance = (dx * dx + dy * dy).squareRoot()
        let rays = 0.55 * pow(0.5 + 0.5 * cos(angle * 13 + 0.7), 5)
            + 0.45 * pow(0.5 + 0.5 * cos(angle * 7 - 1.3), 4)
        let cone = Shade.gaussian(angle, centre: 0, width: 0.75)
        let falloff = exp(-distance * 2.1)
        c = c.under(slot(1), alpha: 0.30 * rays * cone * falloff)
        // The light itself, a soft pool where the rays begin.
        c = c.under(slot(2), alpha: 0.18 * exp(-distance * 5.5))
        return c
    }

    /// A grainy mesh of three soft blobs, warm against cool, kept dark.
    private func grainient(_ u: Double, _ v: Double) -> ShadeColor {
        var c = slot(0)
        let x = u * aspect
        func blob(_ bx: Double, _ by: Double, _ radius: Double) -> Double {
            let dx = x - bx * aspect
            let dy = v - by
            return exp(-(dx * dx + dy * dy) / (radius * radius))
        }
        c = c.under(slot(1), alpha: 0.85 * blob(0.18, 0.22, 0.42))
        c = c.under(slot(2), alpha: 0.55 * blob(0.92, 0.36, 0.34))
        c = c.under(slot(3), alpha: 0.75 * blob(0.42, 0.66, 0.40))
        return c
    }

    /// A fine grid of squares that is only there in the middle, like light
    /// falling on graph paper.
    private func shapeGrid(_ u: Double, _ v: Double) -> ShadeColor {
        var c = slot(0)
        let cell = 0.075
        let gx = (u * aspect).truncatingRemainder(dividingBy: cell) / cell
        let gy = v.truncatingRemainder(dividingBy: cell) / cell
        let line = 0.035
        let onLine = (gx < line || gx > 1 - line || gy < line || gy > 1 - line) ? 1.0 : 0.0
        let spot = exp(-pow(Shade.ellipse(u, v, cx: focus.x, cy: focus.y, rx: 0.75, ry: 0.5), 2) * 1.6)
        c = c.under(slot(1), alpha: 0.10 * onLine * spot)
        c = c.under(slot(2), alpha: 0.35 * spot)
        return c
    }

    // MARK: - Shared

    /// Darkens the band white captions sit in, 75 to 85% down the frame, so
    /// their outline never has to fight the backdrop.
    private func captionBand(_ c: ShadeColor, _ v: Double) -> ShadeColor {
        let band = Shade.smoothstep(0.5, 0.78, v) * (1 - Shade.smoothstep(0.9, 1.0, v) * 0.3)
        return c.scaled(1 - 0.35 * band)
    }
}

// MARK: - Services/Backdrop/BackdropPresetRenderer.swift

/// Paints a preset into a bitmap once, so the compositor only ever composites
/// a still.
///
/// A preset is a function of the pixel and nothing else, so it is drawn on the
/// CPU here rather than as a Core Image kernel: the math is ordinary Swift, it
/// can be tested, and the same numbers port to the agent skill unchanged. A
/// 1080 by 1920 frame takes a few tens of milliseconds across all cores, and
/// the result is cached by preset, size and focus.
enum BackdropPresetRenderer {
    private static let cache = BackdropImageCache()

    static func image(
        _ preset: BackdropPreset,
        width: Int,
        height: Int,
        focus: (x: Double, y: Double) = (0.5, 0.42),
        colors: [String]? = nil
    ) -> CGImage? {
        guard width > 0, height > 0 else { return nil }
        // Rounded so a card nudged a pixel does not repaint the backdrop.
        let fx = (focus.x * 50).rounded() / 50
        let fy = (focus.y * 50).rounded() / 50
        let palette = preset.resolvedColors(colors)
        let key = "\(preset.rawValue)-\(width)x\(height)-\(fx)-\(fy)-\(palette.joined())"
        if let cached = cache.image(for: key) { return cached }

        let shader = BackdropPresetShader(
            preset: preset,
            aspect: Double(width) / Double(height),
            focus: (fx, fy),
            colors: palette
        )
        let bytesPerRow = width * 4
        var pixels = [UInt8](repeating: 255, count: bytesPerRow * height)
        let grain = shader.grain
        pixels.withUnsafeMutableBufferPointer { buffer in
            let base = buffer.baseAddress!
            DispatchQueue.concurrentPerform(iterations: height) { y in
                let v = (Double(y) + 0.5) / Double(height)
                let row = base + y * bytesPerRow
                for x in 0 ..< width {
                    let u = (Double(x) + 0.5) / Double(width)
                    let noise = (Shade.hash(x, y) - 0.5) * 2 * grain
                    let c = shader.color(u, v).adding(noise)
                    let p = row + x * 4
                    p[0] = channel(c.r)
                    p[1] = channel(c.g)
                    p[2] = channel(c.b)
                }
            }
        }

        guard
            let space = CGColorSpace(name: CGColorSpace.sRGB),
            let provider = CGDataProvider(data: Data(pixels) as CFData),
            let image = CGImage(
                width: width,
                height: height,
                bitsPerComponent: 8,
                bitsPerPixel: 32,
                bytesPerRow: bytesPerRow,
                space: space,
                bitmapInfo: CGBitmapInfo(rawValue: CGImageAlphaInfo.noneSkipLast.rawValue),
                provider: provider,
                decode: nil,
                shouldInterpolate: true,
                intent: .defaultIntent
            )
        else { return nil }
        cache.store(image, for: key)
        return image
    }

    private static func channel(_ value: Double) -> UInt8 {
        UInt8(Shade.clamp(value) * 255 + 0.5)
    }
}

/// A small cache of painted backdrops. Thread safe: the composition builder
/// and the inspector's swatches both ask for them.
private final class BackdropImageCache: @unchecked Sendable {
    private let lock = NSLock()
    private var images: [String: CGImage] = [:]
    private var order: [String] = []
    private let limit = 24

    func image(for key: String) -> CGImage? {
        lock.lock()
        defer { lock.unlock() }
        return images[key]
    }

    func store(_ image: CGImage, for key: String) {
        lock.lock()
        defer { lock.unlock() }
        if images[key] == nil { order.append(key) }
        images[key] = image
        while order.count > limit {
            images[order.removeFirst()] = nil
        }
    }
}

// MARK: - Command line

let arguments = CommandLine.arguments.dropFirst().map { $0 }
guard
    arguments.count >= 4,
    let preset = BackdropPreset(rawValue: arguments[0]),
    let width = Int(arguments[1]),
    let height = Int(arguments[2])
else {
    let names = BackdropPreset.allCases.map(\.rawValue).joined(separator: ", ")
    FileHandle.standardError.write(Data("usage: swift render-preset.swift <\(names)> <width> <height> <out.png> [focusX focusY [colors]]\n".utf8))
    exit(2)
}
let focus = arguments.count >= 6
    ? (Double(arguments[4]) ?? 0.5, Double(arguments[5]) ?? 0.42)
    : (0.5, 0.42)
// Optional seventh argument: the preset's colours, background first, comma
// separated (#0D1B3A,#284E92,#5488F5). Missing slots keep the preset's own.
let colors = arguments.count >= 7 ? arguments[6].split(separator: ",").map(String.init) : nil
guard let image = BackdropPresetRenderer.image(preset, width: width, height: height, focus: focus, colors: colors) else {
    FileHandle.standardError.write(Data("could not render \(preset.rawValue)\n".utf8))
    exit(1)
}
let url = URL(fileURLWithPath: arguments[3])
guard let destination = CGImageDestinationCreateWithURL(url as CFURL, UTType.png.identifier as CFString, 1, nil) else { exit(1) }
CGImageDestinationAddImage(destination, image, nil)
guard CGImageDestinationFinalize(destination) else { exit(1) }
print(url.path)
